//! Generated by `cargo run -p xtask -- lua-hooks` from native-hooks.json and the
//! native functions' signatures: edit xtask/src/lua_hooks.rs, then regenerate.

/// The hooks the generator wires into `horizon.on`: the native names, one
/// event table per hook. `horizon.on` rejects a kind for these: the spike
/// answers every event to every handler.
pub const GENERATED_HOOK_NAMES: &[&str] = &[
    "level_tick_pre",
    "chunk_load",
    "block_cook",
    "anvil_damaged",
    "player_container_close",
    "block_burn",
    "bell_ring",
    "arrow_loose",
    "block_lock_check",
    "component_types",
    "datapack_sync",
    "screen_tooltip",
    "is_bonemeal_success",
    "item_fluid_tank",
    "tooltip_component",
    "screen_click",
    "prepare_anvil",
];

/// `{x, y, z}` of a block position, as the hand-written hooks name it.
pub(crate) fn pos_table(lua: &mlua::Lua, pos: [i32; 3]) -> mlua::Result<mlua::Table> {
    let t = lua.create_table()?;
    t.set("x", pos[0])?;
    t.set("y", pos[1])?;
    t.set("z", pos[2])?;
    Ok(t)
}

/// `{x, y}` of a 2D float pair (`screen_click`'s `at`).
pub(crate) fn pair_table(lua: &mlua::Lua, pos: [f32; 2]) -> mlua::Result<mlua::Table> {
    let t = lua.create_table()?;
    t.set("x", pos[0])?;
    t.set("y", pos[1])?;
    Ok(t)
}

/// A number field back as a float: scripts write `16` or `16.0` alike.
pub(crate) fn read_number(t: &mlua::Table, key: &str) -> mlua::Result<f32> {
    match t.get::<mlua::Value>(key)? {
        mlua::Value::Integer(n) => Ok(n as f32),
        mlua::Value::Number(n) => Ok(n as f32),
        v => Err(mlua::Error::runtime(format!(
            "{key}: expected a number, got {}",
            v.type_name()
        ))),
    }
}
/// A `{x, y}` table back into a float pair.
pub(crate) fn read_pair(t: &mlua::Table) -> mlua::Result<[f32; 2]> {
    Ok([read_number(t, "x")?, read_number(t, "y")?])
}

/// An item stack from its table: `id`, `count`, `damage`. Extra
/// components do not survive: a replaced stack is plain.
pub(crate) fn item_from_table(
    table: &mlua::Table,
) -> mlua::Result<horizon_client::mod_api::ItemStack> {
    Ok(horizon_client::mod_api::ItemStack {
        item: std::sync::Arc::from(table.get::<String>("id")?.as_str()),
        count: table.get::<Option<u32>>("count")?.unwrap_or(1),
        damage: table.get::<Option<u32>>("damage")?.unwrap_or(0),
        extra: None,
    })
}

/// A string slice as a sequence table.
pub(crate) fn string_seq(lua: &mlua::Lua, items: &[String]) -> mlua::Result<mlua::Table> {
    lua.create_sequence_from(items.iter().map(String::as_str))
}

/// An int slice as a sequence table.
pub(crate) fn int_seq(lua: &mlua::Lua, items: &[i32]) -> mlua::Result<mlua::Table> {
    lua.create_sequence_from(items.iter().copied())
}

/// A string sequence table back into a vector.
pub(crate) fn read_string_seq(t: &mlua::Table) -> mlua::Result<Vec<String>> {
    t.sequence_values::<String>().collect()
}

