    const MANIFEST_TEXT: &str = "id = \"ruby\"\nname = \"Ruby\"\nversion = \"0.1.0\"\napi = \"0.2\"\nside = \"both\"\ncapabilities = [\"scripts\"]\nexperimental = [\"scripts\"]\n";

    fn hmod(name: &str, lua: &str) -> (PathBuf, PathBuf) {
        let dir =
            std::env::temp_dir().join(format!("horizon-lua-gen-{name}-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&dir);
        std::fs::create_dir_all(&dir).unwrap();
        let path = dir.join("ruby.hmod");
        std::fs::write(
            &path,
            Package::write_files(MANIFEST_TEXT, None, &[("scripts/init.lua", lua.as_bytes())])
                .unwrap(),
        )
        .unwrap();
        (dir, path)
    }

    /// Load a mod running `lua`, with a clean status row: `no_error` then
    /// tells a handler's `assert` from silence.
    fn loaded(name: &str, lua: &str) -> (LuaMod, String, PathBuf) {
        let (dir, path) = hmod(name, lua);
        let m = LuaMod::load(&path, &[]).unwrap();
        let id = m.id().to_owned();
        set_status(ModStatus {
            id: id.clone(),
            ..Default::default()
        });
        (m, id, dir)
    }

    fn boxed(m: LuaMod) -> Vec<Box<dyn Hooks>> {
        vec![Box::new(m) as Box<dyn Hooks>]
    }

    fn drop_dir(dir: PathBuf) {
        std::fs::remove_dir_all(&dir).unwrap();
    }

    /// No `error` row for `id`: every `assert` in its handlers held.
    fn no_error(id: &str) {
        assert!(
            status()
                .into_iter()
                .find(|s| s.id == id)
                .and_then(|s| s.error)
                .is_none(),
            "a handler failed: {:?}",
            status()
                .into_iter()
                .find(|s| s.id == id)
                .and_then(|s| s.error)
        );
    }

